def normalize_doc(row):
    return {
        "doc_id": str(row.get("doc_id") or row.get("id")),
        "title": (row.get("title") or "").strip(),
        "source_url": row.get("url") or row.get("source_url"),
        "lane": row.get("lane", "B"),
    }

def make_chunk_id(doc_id, index):
    return f"{doc_id}::chunk::{index:04d}"

