def embed_in_batches(texts, model, batch_size=32):
    vectors = []
    for start in range(0, len(texts), batch_size):
        batch = texts[start:start + batch_size]
        vectors.extend(model.encode(batch))
    return vectors

def rerank(question, candidates, scorer):
    scored = []
    for chunk in candidates:
        score = scorer(question, chunk["text"])
        scored.append({"chunk": chunk, "score": score})
    return sorted(scored, key=lambda x: x["score"], reverse=True)

def build_evidence_pack(hits):
    pack = []
    for hit in hits:
        pack.append({
            "doc_id": hit["doc_id"],
            "chunk_id": hit["chunk_id"],
            "quote": hit["text"][:300],
            "score": hit.get("score", 0),
        })
    return pack

def make_prompt(question, evidence):
    lines = ["Answer using only the evidence below."]
    for i, ev in enumerate(evidence, start=1):
        lines.append(f"[{i}] {ev['quote']}")
    lines.append("Question: " + question)
    return "\n".join(lines)

def call_with_retry(client, prompt, max_attempts=3):
    if max_attempts < 1:
        raise ValueError("max_attempts must be at least 1")
    for attempt in range(max_attempts):
        try:
            return client.generate(prompt, timeout=60)
        except TimeoutError:
            if attempt == max_attempts - 1:
                raise

def answer_question(question, evidence, llm):
    if len(evidence) < 2:
        return {
            "answer": "I cannot give a definitive answer due to insufficient evidence.",
            "confidence": "low"
        }
    prompt = make_prompt(question, evidence)
    return {"answer": llm(prompt), "confidence": "normal"}

