def run_eval(cases, rag):
    failures = []
    for case in cases:
        result = rag(case["question"])
        if case["must_cite"] and not result.get("citations"):
            failures.append(case["id"])
    return failures

import time

def get_or_fetch(key, cache, fetch, ttl=3600):
    item = cache.get(key)
    if item and time.time() - item["saved_at"] < ttl:
        return item["value"]
    value = fetch(key)
    cache[key] = {"value": value, "saved_at": time.time()}
    return value

import hashlib

def claim_hash(text):
    norm = " ".join(text.lower().split())
    return hashlib.sha256(norm.encode("utf-8")).hexdigest()

def finalize_run(db, run_id, ok, stats, error=None):
    status = "ok" if ok else "error"
    db.update("runs", run_id, {
        "status": status,
        "stats": stats,
        "error_message": str(error) if error else None,
    })
